import * as React from "react";
import { navigate } from "gatsby";

const NotFound = () => {
    React.useEffect(() => {
        if (typeof window !== "undefined") {
            navigate("/portfolio/", { replace: true });
        }
    }, []);

    return (
        <div>
            <h1>Page not found_2</h1>
        </div>
    );
};

export default NotFound;
